# -*- coding: utf-8 -*-
from fams import *
F = 'fblost'
page('facebook-lost-access-old-phone-number', F, 'Facebook Login Code Goes to an Old Phone Number',
 'Facebook sends the login code to a phone number you no longer have? How to get in using another contact, ID or a device Facebook already knows.',
 'Facebook code goes to an old phone number?', 'Code to an old phone number',
 'The number on the account is out of date and the code never reaches you. There are ways around that, the official ones.',
 'If the number on your Facebook account is old, codes go nowhere useful. Try logging in on a phone or computer you have used before, choose another contact option on the screen, and use the lost-access flow with a video selfie or ID if offered. Then update the number once you are in.',
 [('Use a known device', 'Facebook trusts devices it has seen before.'),
  ('Choose another option', 'An email on file may still work.'),
  ('Update the number after', 'Add a current one and an authenticator app.')],
 [S('Why the number matters', 'Facebook uses the phone number and email on file to verify you. If both are out of date, the system cannot send a code and falls back to other checks.',
    ul(['The number was changed or reassigned.', 'The email is an old one.', 'The code arrives late or not at all.'])),
  S('Steps to try', ol(['Use the phone or computer where you are usually logged in.', 'On the login screen choose Need another way to authenticate or similar wording.', 'If offered, follow the video selfie or ID route.', 'Contact us with the screens if the route stops.']))],
 [('Can I just change the number from outside?', 'No. You need to be logged in or verified first.'),
  ('Is an ex holding my number?', 'If someone else controls the old number, treat it as a security issue and use the selfie route.'),
  ('How do I prevent this?', 'Add two or more contacts and keep them current.')],
 ['People who changed their phone number.', 'Owners of old accounts.', 'Anyone whose carrier reassigned the number.'])

page('facebook-hacked-email-changed', F, 'Facebook Hacked and the Email Was Changed',
 'A hacker changed the email on your Facebook account and your reset links no longer arrive? How to use the revert message and the hacked-account route.',
 'Facebook hacked and the email changed?', 'Hacked, email changed',
 'When the email changes, the hacker gets your reset links. The old email may still hold a way back.',
 'When a hacker changes the email on your Facebook account, the reset links go to their address. Check your original inbox for a message about the change, because it often includes a link to undo it. If that link has expired or is missing, use the hacked-account flow from the login screen.',
 [('Search your old inbox', 'Look for Facebook messages dated around the hack.'),
  ('Use the undo link soon', 'It can expire.'),
  ('Do not keep requesting resets', 'They go to the hacker’s address.')],
 [S('What to look for', ul(['A message that your email was changed.', 'A message that a new device logged in.', 'A message about a changed password.', 'A message about a new two-factor method.']),
    'Check spam, promotions and trash too.'),
  S('Steps', ol(['Open the undo link in the original email on a device you trust.', 'If there is none, use the hacked-account help flow from the login screen.', 'Complete the identity step with a video selfie or ID.', 'Change your passwords and log out other sessions after access returns.']))],
 [('How long does the undo link last?', 'We cannot say. Act as soon as you see the email.'),
  ('What if the hacker removed my old email?', 'The hacked-account route is the other path. Tell Facebook and us what happened.'),
  ('Do I need to contact the bank?', 'If payment details were saved on the account, yes, as a precaution.')],
 ['People who see a new email address on their account.', 'Owners whose resets fail.', 'Businesses with saved payment details.'])

page('facebook-no-password-reset-options-shown', F, 'Facebook Shows No Password Reset Options',
 'You try to reset your Facebook password and no email or phone option appears? Why this happens and how to get to the other recovery paths.',
 'Facebook shows no password reset options?', 'No reset options shown',
 'A blank list of options means Facebook has no usable contact for the account, or has held it for security reasons.',
 'If Facebook shows no way to reset your password, the contacts on the account may be unusable, or the account is on hold for security. Try the account search with each email and phone you have used, try from a trusted device, and look for a link saying you no longer have access to these.',
 [('Search with each contact', 'An old email or number may find the right account.'),
  ('Try a trusted device', 'Facebook is more helpful on known devices.'),
  ('Look for the fallback link', 'There is usually a link for people who cannot use the options shown.')],
 [S('Why the list is empty', ul(['The account is on hold after suspicious activity.', 'The email and phone are not verified or are removed.', 'A hacker removed the recovery options.', 'You found a different account with a similar name.']),
    'It is worth checking you are looking at the right account.'),
  S('What to try', ol(['Search by each email, phone number and username you might have used.', 'Open the page from a phone or computer you used before.', 'Select the link that says you no longer have access.', 'Send us what you see if no option comes up.']))],
 [('Will I be asked for ID?', 'Possibly. Use the official screen only.'),
  ('Can I make a new account?', 'You can, but it does not bring the old one back. Do not use it to evade a ban.'),
  ('Is the hold temporary?', 'Sometimes. A short break from the account can help.')],
 ['People with a blank reset screen.', 'Owners of old accounts.', 'Anyone who changed phones and emails over the years.'])

page('facebook-recovery-code-sent-to-wrong-email', F, 'Facebook Recovery Code Sent to the Wrong Email',
 'Facebook says the recovery code was sent to an email you do not recognise? What that address usually means and what to do about it.',
 'Facebook sends the recovery code to a strange email?', 'Code sent to an unknown email',
 'A masked address that is not yours is a signal. It tells you something about the account.',
 'If the masked email shown by Facebook does not look like yours, it can be an old address you forgot, a typo made at sign-up, or an address a hacker added. Think through your own old addresses first. If none fit, treat it as a hack and use the lost-access flow with identity verification.',
 [('Think through old addresses', 'Old work, school and provider emails are common.'),
  ('Check for a typo at sign-up', 'A wrong letter at sign-up sends mail to a stranger.'),
  ('Treat it as a hack if none fit', 'Use the identity route.')],
 [S('Ways this arises', ul(['An old email you forgot you used.', 'A typo made when you registered.', 'A hacker changed it.', 'A workplace address that no longer exists.']),
    'The masked address shows the first letter and the domain, which can help you remember.'),
  S('What to do', ol(['Write down every email you have ever had and check which matches the first letters.', 'If one matches and you still have it, request the code there.', 'If none match, use the link that says you no longer have access.', 'Follow the identity steps and tell us the result.']))],
 [('Can I read the full address?', 'No. Facebook masks it. Use the visible letters and domain as clues.'),
  ('What if it is a hacker’s address?', 'You need identity verification to take the account back.'),
  ('Will changing the address after help?', 'Yes, once you are in. Add a current email and phone.')],
 ['People with a masked address they do not recognise.', 'Owners of old accounts.', 'Anyone who made a typo at sign-up.'])

page('facebook-hacked-ads-charged-to-my-card', F, 'Facebook Hacked and Ads Were Charged to Your Card',
 'A hacker ran ads on your hacked Facebook account and charges appeared on your card? What to stop first, what to document and how to recover.',
 'Facebook hacked and ads charged to your card?', 'Hacked with ad charges',
 'Money leaving your account is the urgent part. Handle that first, then work on getting back in.',
 'If a hacker ran ads on your Facebook account, stop the spending first: contact your bank to block further charges, then remove the card from your ad account if you can reach it. Document each charge, then start recovery of the profile, review all admins, and appeal any ad account restrictions with a short note.',
 [('Stop the charges', 'Ask your bank to block them or replace the card.'),
  ('Document everything', 'Screenshots of ads and statement lines.'),
  ('Then recover access', 'Secure the email, then use the hacked-account flow.')],
 [S('What to check', ul(['Billing activity in the ad account.', 'The list of admins and users on Pages and ad accounts.', 'Active campaigns and who created them.', 'Connected Instagram accounts.']),
    'Contact your card issuer if charges seem fraudulent. The reimbursement process is between you, your bank and Meta’s billing.'),
  S('Order of work', ol(['Call your bank, and remove or replace the card.', 'Secure the email and change passwords.', 'Use the hacked-account recovery flow for the profile.', 'If the ad account is restricted, see our Meta ad account pages and tell us the notice.']))],
 [('Will the ads stop on their own?', 'No. Pause them if you can reach the account, and cut the payment method.'),
  ('Could the ad account be disabled?', 'Yes. Ads from a hacker can trigger a restriction. Explain the hack in your appeal.'),
  ('Can Unbanz get the money back?', 'No. That is a matter for your bank and Meta’s billing.')],
 ['Owners who see ad charges they did not make.', 'Pages with a saved card.', 'Businesses with a hacked admin.'])

page('facebook-hacked-by-someone-i-know', F, 'Facebook Hacked by Someone You Know',
 'You think an ex, relative or colleague got into your Facebook account? Practical steps for removing their access and recovering control.',
 'Facebook hacked by someone you know?', 'Hacked by an acquaintance',
 'Someone close can guess answers and passwords, or already has your device. That calls for a different approach.',
 'When the person who got into your account knows you, they may use a saved device, guessed passwords, or access to your email or phone. Secure the email first from a device they do not have, change passwords, log out all sessions and remove unknown devices. If you fear for your safety, consider a trusted person or the authorities.',
 [('Use a device they cannot reach', 'A new phone or a friend’s device while you change things.'),
  ('Change the email first', 'It is the master key.'),
  ('Remove other sessions', 'Log out all devices and review the list.')],
 [S('Why it is different', ul(['They may know your security answers.', 'They may have your phone or laptop.', 'They may have your email password.', 'They may share your Wi-Fi, so location checks pass.']),
    'Everyday security checks assume a stranger. Here they may not work well.'),
  S('Steps', ol(['Change the email password and set up two-factor on it using an authenticator app.', 'Change the Facebook password, then log out of all sessions.', 'Remove any device you do not recognise from the security settings.', 'If you cannot get in, use the lost-access flow and tell us what you see.']),
    'If there is stalking or harassment, tell the police and keep records. Unbanz is not a safety service.')],
 [('Can I see who logged in?', 'Security settings show a list of logins and devices on many accounts.'),
  ('Should I confront them?', 'That is up to you. Secure the account first.'),
  ('Will Facebook act on suspicion?', 'The route is the same as any hacked account. Evidence helps.')],
 ['People in shared households.', 'Ex-partners’ accounts that are still linked.', 'Colleagues who shared a login.'])

page('facebook-hacked-name-and-photo-changed', F, 'Facebook Hacked, Name and Profile Photo Changed',
 'Your Facebook profile shows a new name and photo after a hack? What this means, why hackers do it and which steps to take to recover and fix it.',
 'Facebook hacked, name and photo changed?', 'Name and photo changed',
 'A changed name and photo mean the account was taken over, not that it was deleted. Here is how to respond.',
 'Hackers often change the name and photo to use your profile for scams or to hide it from friends. Treat it as a full takeover: secure the email, use the hacked-account flow, and once you are back in, restore the name and photo and review everything else. Name changes are limited, so tell Facebook about the hack.',
 [('It is a takeover', 'Use the hacked-account route.'),
  ('Warn friends', 'The profile may be used for scams.'),
  ('Fix the name after', 'Name changes may be limited, so mention it in the request.')],
 [S('Why hackers do it', ul(['To hide the profile from friends who would notice.', 'To use it for a scam or fake store.', 'To sell it or the access.', 'To impersonate someone else.']),
    'Often the hacker also changes the email.'),
  S('Steps', ol(['Check your original email for a change alert.', 'Open the hacked-account flow on the login screen.', 'Write that the name and photo were changed by someone else.', 'After recovery, restore your name, photo and privacy settings.']))],
 [('Can I change the name back at once?', 'Facebook limits name changes. Explain in the recovery request.'),
  ('Will my friends still see the profile?', 'Yes, until recovery. Warn them elsewhere.'),
  ('Is this common?', 'Yes. It is a typical sign of a takeover.')],
 ['People who see someone else’s name on their profile.', 'Page admins whose profile was taken.', 'Owners of old accounts.'])

page('facebook-hacked-marketplace-listings-posted', F, 'Facebook Hacked, Marketplace Listings You Did Not Post',
 'A hacker posted Marketplace listings from your Facebook account? How this leads to flags, what to remove and how to appeal fraud reports.',
 'Hacker posted Marketplace listings from your account?', 'Hacked, Marketplace listings',
 'Fake listings from your profile put your name on a scam. Handle the account, then the listings.',
 'A hacker who posts fake Marketplace listings can leave your account flagged and reported. Secure the account, then remove the listings and message anyone who contacted you about them. Appeal any restriction and say that you did not create them. Keep screenshots of the listings and the dates.',
 [('Secure the account first', 'Email, password, and sessions.'),
  ('Remove the listings', 'Then tell buyers who contacted you.'),
  ('Explain the hack', 'In any appeal for restrictions.')],
 [S('What these scams look like', ul(['Cars, phones or rentals far below their usual value.', 'Requests to move the chat to another app.', 'Deposits asked before any meeting for items that do not exist.', 'Buyers reported to you for not receiving anything.']),
    'People who dealt with the fake listing may report your profile.'),
  S('What to do', ol(['Get access back using the hacked-account flow if you do not have it.', 'Remove every listing and note their dates.', 'Tell people who messaged about them that the listings were fake.', 'Appeal any Marketplace restriction and attach the screenshots.']))],
 [('Could Marketplace be blocked for me?', 'It can. Appeals explain that a hacker created the listings.'),
  ('Do I have to pay buyers back?', 'Money paid to a hacker is a police matter. Facebook cannot reverse it.'),
  ('How do I prevent it?', 'Use two-factor, a unique password and never log in through links.')],
 ['People whose friends spotted fake listings.', 'Sellers with Marketplace restrictions after a hack.', 'Owners who see items they never posted.'])

page('facebook-hacked-messenger-scam-messages', F, 'Facebook Hacked, Scam Messages Sent Through Messenger',
 'A hacker is messaging your contacts on Messenger asking for money? How to warn people, cut off the account and start recovery.',
 'Messenger scam messages sent from your hacked Facebook?', 'Hacked, Messenger scams',
 'Friends trust messages that appear to come from you. That is why these scams work.',
 'If your hacked account messages your friends on Messenger asking for money or gift cards, warn them by another channel. Do not reply to the hacker. Report the messages, secure your email, and use the hacked-account recovery flow. Tell friends who paid anything to contact their bank and the police.',
 [('Warn by phone or email', 'Do not rely on Facebook, since the hacker holds it.'),
  ('Do not reply to the hacker', 'It will not return the account.'),
  ('Tell anyone who paid', 'They should call their bank at once.')],
 [S('Common messages', ul(['A request for a short loan or a gift card code.', 'A link described as a video of the recipient.', 'A request to vote in a contest by logging in.', 'An urgent request to confirm a code sent by SMS.']),
    'The last one is a way to take over the recipient’s account, so friends should never share codes.'),
  S('Steps', ol(['Send a short warning by text or email to your closest contacts.', 'Secure your email, then start the Facebook hacked-account flow.', 'Report scam messages you can still see.', 'After access returns, change passwords and log out other sessions.']))],
 [('Do friends need to report anything?', 'They can report the messages as scams through Messenger.'),
  ('Will Facebook warn my contacts?', 'It may reduce reach once reported. Do not rely on it.'),
  ('Is my Messenger history exposed?', 'A hacker can read it while they have access, which is another reason to act.')],
 ['People whose friends send worried messages.', 'Community admins and local business owners.', 'Anyone who sees sent messages they did not write.'])

page('facebook-lost-access-after-changing-phone', F, 'Facebook Lost After Changing Phone: How to Get Back In',
 'You got a new phone and cannot log in to Facebook because the codes went to the old one? Steps for using the old device, backup options and recovery.',
 'Cannot log in to Facebook after changing phone?', 'Lost access after a new phone',
 'A phone upgrade is the most common reason people lose two-factor access. These are the first things to check.',
 'After a phone change, codes may still go to the old device or number. If you still have the old phone, log in there and move the login or generate backup codes. If not, use the recovery flow: another contact method, a video selfie or ID. Add a new method after you are back in.',
 [('Find the old phone', 'It may still be logged in. Use it to move your setup.'),
  ('Check authenticator apps', 'The codes may live in an app you did not move.'),
  ('Use backup codes', 'If you saved them, now is when they matter.')],
 [S('Why it breaks', ul(['The authenticator app stayed on the old phone.', 'SMS codes go to a SIM you no longer use.', 'The new phone has no saved login.', 'The recovery email is old.'])),
  S('Steps', ol(['If the old phone still works, log in there and add the new phone as a device.', 'Look for saved backup codes in notes, email or a password manager.', 'If you have neither, use the lost-access option and follow the selfie or ID steps.', 'Once in, set up two-factor on the new phone and store backup codes safely.']))],
 [('Can I move my authenticator app?', 'Many apps have an export. Check before wiping the old phone next time.'),
  ('What if the old phone is broken?', 'Use the lost-access route and identity checks.'),
  ('Is the account safe meanwhile?', 'It is locked to you but not to anyone else. Keep your email secure.')],
 ['People who upgraded phones.', 'Owners whose old phone was lost or damaged.', 'Anyone who relied on a single device.'])
